with recent_orders as (select *, amount - shipping_fee as amount_with_shipping from orders where (channel = 'web' and customer_id is null) or store_id is null), order_month_summary as (select date_format(order_date, 'yyyy-MM') as order_month, year(order_date) as order_year, sum(case when status = 'RETURNED' then 1 else 0 end) as returned_count from recent_orders group by date_format(order_date, 'yyyy-MM'), year(order_date)) select * from order_month_summary order by returned_count;
